const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const curriculum = [["Gerald, Sheila, and power", "Finish Act 2 from Gerald\u2019s departure. Mark two statements by Mrs. Birling.", "Explore power in relationships and compare left/right beliefs, motivations, and shared goals."], ["Mrs. Birling and responsibility", "Read Act 3 through Eric\u2019s account, stopping before the Inspector\u2019s final speech.", "Explain dramatic irony and consider wages, worker protection, and business costs."], ["Eric\u2019s account", "Read the Inspector\u2019s final speech and departure. Mark three persuasive language choices.", "Analyze individual responsibility and consider charity, taxation, and public support."], ["The Inspector\u2019s final speech", "Finish Act 3. Note the characters\u2019 different reactions.", "Analyze persuasive language and historical context; compare universal services and targeted assistance."], ["An ending that asks questions", "Reread Birling\u2019s Act 1 business speech and the Inspector\u2019s final speech. Select two quotations.", "Analyze contrasting reactions and structure; explore government, parliament, and accountability."], ["Comparing arguments", "Read Lord of the Flies, Chapter 1. Note first impressions of Ralph, Piggy, and Jack.", "Write a supported response; distinguish economic beliefs from democratic or authoritarian methods."], ["The island and the conch", "Reread the leadership election in Chapter 1. Mark evidence about the candidates.", "Analyze setting and characterization; explore leadership, expertise, and consent."], ["Who gets a voice?", "Read Chapter 2. Track decisions about the signal fire.", "Analyze the election and emerging conflict; consider representation and safeguards for minorities."], ["Fire and consequences", "Read Chapter 3. Note the disagreement about hunting and shelters.", "Explain unintended consequences; explore shared resources and cooperation."], ["Conflicting priorities", "Read Chapter 4. Notice the painted faces, missed rescue, and treatment of Piggy.", "Compare priorities; evaluate rules, incentives, and voluntary cooperation."], ["Identity and belonging", "Reread the missed-rescue episode and Ralph\u2013Jack confrontation. Identify contrasting priorities.", "Analyze identity and belonging; examine framing and persuasive language."], ["The fire and the glasses", "Read Chapter 5. Track different explanations of the beast.", "Explain conflict and symbolism; check claims against another source."], ["Fear and authority", "Read Chapter 6. Separate what the reader knows from what the boys believe.", "Analyze weakening authority; weigh security and freedom."], ["What the reader knows", "Read Chapter 7. Note changes in Ralph during the hunt and search.", "Explain dramatic irony and mistaken belief; consider proportionate responses and safeguards."], ["Pressure to belong", "Read Chapter 8 with appropriate support. Track Jack\u2019s leadership challenge and promises.", "Analyze group pressure; explore geography, resources, and trade routes."], ["Divided leadership", "Read Chapter 9 with advance context. Note storm imagery and group language.", "Analyze power; compare trade, dependence, and self-sufficiency."], ["The crowd and the storm", "Reread selected passages from Chapter 9. Find two examples of collective language.", "Analyze perception and imagery; identify misinformation and corroborate claims."], ["Collective responsibility", "Read Chapter 10. Note the competing accounts and what happens to the glasses.", "Evaluate individual and collective responsibility; verify and report a disputed claim."], ["Denial and symbolism", "Read Chapter 11 with advance context. Track Piggy\u2019s appeal and the conch.", "Analyze denial; explore rights, due process, and the rule of law."], ["The collapse of rules", "Read Chapter 12. Notice the contrast between the pursuit and rescue.", "Analyze the collapse of agreed rules; consider refugee protection, capacity, and fair procedures."], ["Rescue and the wider world", "Reread the ending and Chapter 1\u2019s leadership vote. Select two contrasting details.", "Analyze irony and the wider war; explore sovereignty, diplomacy, and the UN."], ["Looking across both texts", "Reread two passages from each text and two short sources on a previously studied issue.", "Compare Golding and Priestley; negotiate international cooperation."], ["Build your comparison", "Reread the draft, feedback, quotations, and news extracts. Identify one revision and one unsupported claim.", "Draft a supported comparison and prepare a balanced current-affairs briefing."], ["Present, reflect, and grow", "Reread feedback and one passage now understood more deeply. No new chapter reading.", "Revise and present writing; explain alternatives and uncertainties in a current-affairs briefing."]];
const topics = curriculum.map(r=>r[0]);
const readings = curriculum.map(r=>r[1]);
const goals = curriculum.map(r=>r[2]);
let state;
try { state = JSON.parse(localStorage.getItem('inkwire-v2') || '{}'); } catch { state = {}; }
state.notes ||= {}; state.richNotes ||= {}; state.quizzes ||= {}; state.assessments ||= {}; state.plan ||= {}; state.preparation ||= {};
let week = 1, student = 'Alex Lee', section = 'Discussion', toastTimer;
function save(){try{localStorage.setItem('inkwire-v2', JSON.stringify(state));return true;}catch{toast('Unable to save in this browser. Please copy your work.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);}
function plan(n){return {title:topics[n-1],reading:readings[n-1],goal:goals[n-1],...state.plan[n]};}
function heading(label,title,sub){return '<div class="heading"><div><div class="eyebrow">'+label+'</div><h1>'+title+'</h1><p class="muted">'+sub+'</p></div><span class="pill">Autumn semester · 12 weeks · 24 lessons</span></div>';}
function noteKey(){return student+'|'+week+'|'+section;}
function assessmentKey(){return student+'|'+week;}
function quizDone(){return !!state.quizzes['Alex Lee|1'];}
function timeline(){return heading('The big picture','Your 12-week learning journey','An Inspector Calls → Lord of the Flies · Literature, politics, and current affairs.')+'<div class="notice">Two lessons per week. Reading assignments are due after the listed lesson, before the next one. Current-affairs materials will be selected by your teacher.</div><div class="timeline">'+Array.from({length:12},(_,i)=>'<article class="card '+(i===0?'selected':'')+'"><div class="eyebrow">WEEK '+String(i+1).padStart(2,'0')+'</div>'+[1,2].map(l=>{const n=i*2+l,p=plan(n);return '<div class="task" style="display:block"><span class="tag">LESSON '+l+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.goal)+'</p><p class="muted"><b>After this lesson</b><br>'+esc(p.reading)+'</p>'+(role==='parent'?'':'<button class="btn secondary openweek" data-week="'+n+'">Open lesson →</button>')+'</div>';}).join('')+'</article>').join('')+'</div>';}
function notebook(){const p=plan(week);return heading('YOUR IDEAS LIVE HERE','Week '+Math.ceil(week/2)+' · Lesson '+((week-1)%2+1)+' · '+esc(p.title),'Literature & the World / Personal notebook')+'<div class="row"><label for="week">Lesson</label><select id="week" style="max-width:320px">'+topics.map((t,i)=>'<option value="'+(i+1)+'" '+(week===i+1?'selected':'')+'>Week '+Math.ceil((i+1)/2)+' · Lesson '+(i%2+1)+' · '+esc(plan(i+1).title)+'</option>').join('')+'</select></div><div class="notice"><b>Learning goal:</b> '+esc(p.goal)+'<br><b>Assignment after this lesson:</b> '+esc(p.reading)+'</div><div class="tabs">'+['Discussion','Writing','Reflection','Homework'].map(s=>'<button class="'+(section===s?'active':'')+'" data-section="'+s+'">'+s+'</button>').join('')+'</div><section class="card notebook"><div class="cardtop"><h2>'+section+'</h2><span id="savestatus" class="muted">Saved in this browser</span></div><p>'+({Discussion:'What stands out in this week’s reading? Record a question, a quotation reference, and your interpretation.',Writing:'How does the writer develop the idea explored in this lesson? Write a PEEEL paragraph: point, evidence, explanation, exploration, and link.',Reflection:'What changed in your understanding today? Explain one success and one next step.',Homework:'Revise your paragraph using feedback. Record your changes and check the next week’s reading assignment.'}[section])+'</p><div class="formlabel">Your response</div><div id="teacher-editor-toolbar" class="notebook-toolbar" role="group" aria-label="Text formatting"></div><div id="teacher-editor"></div><div class="notice">Notebook saves in this browser. Live collaboration and comments are not connected yet.</div></section>';}
const questions=[{q:'Which relationship is central to Gerald’s account in Act 2?',options:['His relationship with Daisy Renton','His friendship with Eric','His business partnership with the Inspector'],answer:0,why:'Gerald explains his relationship with Daisy Renton, the name Eva used.'},{q:'Why does Sheila return Gerald’s ring?',options:['She thinks it belongs to Eva','Her understanding of their relationship has changed','The Inspector orders her to'],answer:1,why:'Sheila reassesses their relationship after hearing Gerald’s account.'},{q:'What gives Gerald power in his relationship with Daisy?',options:['His position as a police officer','His money and social position','His authority as her teacher'],answer:1,why:'His resources and social standing create an unequal relationship.'},{q:'Which approach makes a strong interpretation of Sheila’s response?',options:['Only describe what happens','Assume all readers agree','Support a claim with specific evidence'],answer:2,why:'Specific evidence makes an interpretation reasoned and open to discussion.'}];
function quiz(){const result=state.quizzes['Alex Lee|1'];return heading('PREPARE TO PARTICIPATE','Your ticket into class','Lesson 1 · An Inspector Calls, Act 2 · About 5 minutes')+'<div class="grid"><section class="card"><h2>Bring your reading to the conversation.</h2><p class="muted">Completion counts. If you miss a question, revisit the text and try again.</p>'+(result?'<div class="notice"><b>Preparation complete · '+result.score+'/4</b><br>Your entry ticket is ready. You can review and retry below.</div>':'')+'<form id="quizform">'+questions.map((q,i)=>'<fieldset class="question"><legend>'+(i+1)+'. '+q.q+'</legend>'+q.options.map((o,j)=>'<label class="option"><input required type="radio" name="q'+i+'" value="'+j+'" '+(result?.answers[i]===j?'checked':'')+'>'+o+'</label>').join('')+(result?'<p class="muted">'+(result.answers[i]===q.answer?'✓ Correct. ':'Revisit this idea. ')+q.why+'</p>':'')+'</fieldset>').join('')+'<label class="formlabel" for="reflection">5. What would you like to discuss in class?</label><textarea id="reflection" name="reflection" required minlength="5" placeholder="Ask a question or describe an idea you want to explore.">'+esc(result?.reflection||'')+'</textarea><p><button class="btn">'+(result?'Submit another attempt':'Submit preparation quiz')+' →</button></p></form></section><aside><section class="card"><div class="eyebrow">WHY AN ENTRY TICKET?</div><h3>Arrive with something to say.</h3><p class="muted">This quick check helps your teacher see what you understand and where the conversation should begin.</p><ul class="goals"><li>Use your book.</li><li>Take your time.</li><li>Questions are welcome.</li></ul></section></aside></div>';}
function options(values,value){return '<option value="">Select…</option>'+values.map(v=>'<option '+(value===v?'selected':'')+'>'+v+'</option>').join('');}
function teacher(){const a=state.assessments[assessmentKey()]||{},p=plan(week);return heading('TEACHER STUDIO','Small observations. Meaningful progress.','Record a quick assessment and shape the next lesson.')+'<div class="notice">Demo teacher view · These controls are for exploring the workflow, not an authenticated staff area. Use fictional information only.</div><div class="grid"><section class="card"><h2>Post-lesson assessment</h2><div class="ratinggrid"><div><label class="formlabel" for="student">Student</label><select id="student">'+['Alex Lee','Jamie Chen','Sam Rivera'].map(n=>'<option '+(student===n?'selected':'')+'>'+n+'</option>').join('')+'</select></div><div><label class="formlabel" for="assessweek">Lesson</label><select id="assessweek">'+topics.map((_,i)=>'<option value="'+(i+1)+'" '+(week===i+1?'selected':'')+'>Week '+Math.ceil((i+1)/2)+' · Lesson '+(i%2+1)+'</option>').join('')+'</select></div></div><form id="assessment"><div class="ratinggrid">'+[['attendance','Attendance',['Present','Absent','Rescheduled']],['attitude','Attitude',['Engaged','Responds to encouragement','Needs support']],['homework','Homework completion',['Complete','Partial','Not submitted','Not assigned']],['preparation','Preparation',['Ready','Partly ready','Unprepared']],['participation','Participation and collaboration',['Contributes constructively','Contributes with prompting','Needs support']],['focus','Effort and focus',['Sustained','Inconsistent','Frequent redirection']],['learning','Learning goals',['Secure','Developing','Needs support']]].map(([k,label,values])=>'<div><label class="formlabel" for="'+k+'">'+label+'</label><select required id="'+k+'" name="'+k+'">'+options(values,a[k])+'</select></div>').join('')+'</div><label class="formlabel" for="summary">Lesson recap · shared with student and parent</label><textarea id="summary" name="summary" placeholder="What did we explore? Review your summary before sharing.">'+esc(a.summary||'')+'</textarea><label class="formlabel" for="success">Success · shared with student and parent</label><input id="success" name="success" value="'+esc(a.success||'')+'" placeholder="You supported your interpretation with evidence."><label class="formlabel" for="next">Next step · shared with student and parent</label><input id="next" name="next" value="'+esc(a.next||'')+'" placeholder="Explain how your evidence supports your point."><label class="formlabel" for="private">Teacher note · excluded from student and parent views</label><textarea id="private" name="private" style="min-height:85px">'+esc(a.private||'')+'</textarea><p><button class="btn">Save assessment</button></p></form></section><aside>'+teacherTranscriptPanel()+'<section class="card"><h2>Preparation overview</h2>'+['Alex Lee','Jamie Chen','Sam Rivera'].map(n=>'<div class="task"><span class="avatar">'+n.split(' ').map(x=>x[0]).join('')+'</span><div><b>'+n+'</b><p>'+(n==='Alex Lee'&&quizDone()?'Lesson 1 quiz complete · '+state.quizzes['Alex Lee|1'].score+'/4':'No quiz submitted')+'</p></div></div>').join('')+'</section><section class="card"><h2>Edit Lesson '+week+' plan</h2><form id="planform"><label class="formlabel" for="title">Lesson focus</label><input id="title" name="title" required value="'+esc(p.title)+'"><label class="formlabel" for="reading">Reading assignment</label><input id="reading" name="reading" required value="'+esc(p.reading)+'"><label class="formlabel" for="homework-task">Written homework · optional</label><input id="homework-task" name="homework" value="'+esc(p.homework||'')+'" placeholder="Add a specific task for this lesson"><label class="formlabel" for="goal">Learning goal</label><textarea id="goal" name="goal" required style="min-height:100px">'+esc(p.goal)+'</textarea><p><button class="btn secondary">Save lesson plan</button></p></form></section></aside></div>';}
function feedback(){const entries=Object.entries(state.assessments).filter(([key])=>key.startsWith('Alex Lee|')).sort((a,b)=>Number(b[0].split('|')[1])-Number(a[0].split('|')[1]));return heading('NOTICE YOUR PROGRESS','Feedback for your next chapter','Celebrate a success. Choose a next step. Keep going.')+(entries.length?entries.map(([key,a])=>'<section class="card"><div class="eyebrow">LESSON '+key.split('|')[1]+' · TEACHER FEEDBACK</div><h3>Your success</h3><p>'+esc(a.success||'No success note added yet.')+'</p><h3>Your next step</h3><p>'+esc(a.next||'No next step added yet.')+'</p><a class="link" href="#notebook">Return to your notebook →</a></section>').join(''):'<section class="card"><h2>A fresh page.</h2><p class="muted">Your teacher’s feedback will appear here after a lesson. Review your next step here after your teacher adds feedback.</p></section>');}

const roleParam=new URLSearchParams(location.search).get('role');
const role=['student','teacher','parent'].includes(roleParam)?roleParam:'student';
const roleConfig={
 student:{label:'Student',defaultRoute:'dashboard',routes:['dashboard','timeline','tasks','notebook','quiz','feedback'],links:[['dashboard','◈','Overview'],['timeline','▦','Course timeline'],['tasks','☷','Reading & tasks'],['notebook','▤','My notebook'],['quiz','✓','Preparation quiz'],['feedback','◎','My feedback']],name:'Alex Lee',initials:'AL'},
 teacher:{label:'Teacher',defaultRoute:'teacher',routes:['teacher','timeline','notebook','feedback'],links:[['teacher','✎','Teacher dashboard'],['timeline','▦','Course timeline']],name:'Matthew Gilfillan',initials:'MG'},
 parent:{label:'Parent',defaultRoute:'parent',routes:['parent','timeline','parent-progress','parent-contact'],links:[['parent','◎','Overview'],['timeline','▦','Weekly plan'],['parent-progress','◈','Progress & feedback'],['parent-contact','✉','Contact Matthew']],name:'Alex’s family',initials:'AL'}
}[role];
function setupWorkspace(){
document.body.classList.toggle('parent-workspace',role==='parent');
document.body.classList.toggle('student-workspace',role==='student');
document.querySelector('#workspace-label').textContent=roleConfig.label+' workspace';
document.querySelector('.sidebar nav').innerHTML=roleConfig.links.map(([r,icon,label])=>'<a href="#'+r+'">'+icon+' <span>'+label+'</span></a>').join('')+'<a class="studio-home" href="./">← Back to Ink Wire</a>';
document.querySelector('.sidebottom').innerHTML='<span class="avatar">'+roleConfig.initials+'</span><div><b>'+roleConfig.name+'</b><small>'+roleConfig.label+' demo · 12-week program</small></div>';
document.title=roleConfig.label+' dashboard | Ink Wire';
}


function mountNotebookEditor(elementId,toolbarId,key,statusId,countId,label) {
  const element=document.getElementById(elementId),toolbar=document.getElementById(toolbarId);
  const status=document.getElementById(statusId),text=state.notes[key]||'';
  const changed=({document:rich,text:value})=>{
    state.notes[key]=value;state.richNotes[key]=rich;
    status.textContent=save()?'Saved just now':'Not saved — download or copy your work';
    if(countId)document.getElementById(countId).textContent=studentWordCount(value)+' words';
  };
  if(window.InkWireEditor){
    window.InkWireEditor.mount({element,toolbar,document:state.richNotes[key],text,label,onChange:changed,
      onRecovery:()=>{status.textContent='Text recovered. Formatting could not be loaded.';}});
  }else{
    status.textContent='Text-only mode — formatting unavailable';
    const input=document.createElement('textarea');input.setAttribute('aria-label',label);input.value=text;
    input.addEventListener('input',()=>changed({document:null,text:input.value}));element.append(input);
  }
}

function render(){window.InkWireEditor?.destroy();const route=location.hash.slice(1)||roleConfig.defaultRoute;const views={dashboard:studentDashboard,timeline:role==='parent'?parentWeekPlan:role==='student'?studentTimeline:timeline,tasks:studentTasks,notebook:role==='student'?studentNotebook:notebook,quiz:studentQuiz,teacher,feedback:role==='student'?studentFeedback:feedback,parent:parentDashboard,'parent-progress':parentProgress,'parent-contact':parentContact};const selected=roleConfig.routes.includes(route)&&views[route]?route:roleConfig.defaultRoute;if(selected==='notebook')student='Alex Lee';$('#app').innerHTML=views[selected]();$('#crumb').textContent={dashboard:'Overview',timeline:'Course timeline',tasks:'Reading & tasks',notebook:'My notebook',quiz:'Preparation quiz',teacher:'Teacher studio',feedback:'My feedback',parent:'Overview','parent-progress':'Progress & feedback','parent-contact':'Contact Matthew'}[selected];document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+selected;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(role==='parent'&&selected==='timeline')$('#crumb').textContent='Weekly plan';
bindParentEvents();bindStudentEvents();bindTranscriptEvents();
$('#read')?.addEventListener('click',()=>{state.read=!state.read;save();render();});
$('#join')?.addEventListener('click',()=>toast('Demo: your assigned Zoom link will be connected during account setup.'));
document.querySelectorAll('.openweek').forEach(b=>b.addEventListener('click',()=>{week=Number(b.dataset.week);location.hash='notebook';}));
$('#week')?.addEventListener('change',e=>{week=Number(e.target.value);render();});
document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>{section=b.dataset.section;render();}));
if($('#teacher-editor'))mountNotebookEditor('teacher-editor','teacher-editor-toolbar',noteKey(),'savestatus',null,'Your response');
$('#quizform')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const answers=questions.map((_,i)=>Number(d.get('q'+i)));state.quizzes['Alex Lee|1']={answers,score:answers.filter((v,i)=>v===questions[i].answer).length,reflection:d.get('reflection'),at:new Date().toISOString()};if(save())toast('Preparation complete. Your entry ticket is ready.');render();window.scrollTo(0,0);});
$('#student')?.addEventListener('change',e=>{student=e.target.value;render();});
$('#assessweek')?.addEventListener('change',e=>{week=Number(e.target.value);render();});
$('#assessment')?.addEventListener('submit',e=>{e.preventDefault();state.assessments[assessmentKey()]=Object.fromEntries(new FormData(e.target));if(save())toast('Assessment saved for '+student+'.');});
$('#planform')?.addEventListener('submit',e=>{e.preventDefault();state.plan[week]=Object.fromEntries(new FormData(e.target));if(save())toast('Lesson '+week+' plan updated.');});
}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});setupWorkspace();render();


// Merge cross-tab updates for every role. Keep active editing forms intact.
window.addEventListener('storage',event=>{
  if(event.key==='inkwire-v2'){
    try{const fresh=JSON.parse(event.newValue || '{}');if(!fresh || typeof fresh!=='object')return;state={...fresh,notes:fresh.notes||{},richNotes:fresh.richNotes||{},quizzes:fresh.quizzes||{},assessments:fresh.assessments||{},plan:fresh.plan||{},preparation:fresh.preparation||{}};if(role!=='teacher' && location.hash!=='#parent-contact' && !(role==='student' && ['#notebook','#quiz'].includes(location.hash)))render();}catch{/* Preserve the current view if stored data is invalid. */}
  }
  if(role==='parent' && event.key==='inkwire-parent-read-v1'){
    try{parentRead=JSON.parse(event.newValue || '{}') || {};if(location.hash!=='#parent-contact')render();}catch{/* Preserve current read markers. */}
  }
});
